Empty workspace. Create the project. Write render.js implementing a small markdown subset with escaping-first approach, then tests.

Design render.js:

- escapeHtml: escapes &, <, >, ", '
- Process block-level: split into lines; fenced code blocks ``` ... ```; unordered lists (consecutive lines starting with "- "); paragraphs otherwise.
- Inline: order matters — inline code first (extract placeholders), then links, then bold, then italics. All source text escaped before markup insertion.

Approach for inline:
1. Escape entire text first? But link URLs need allowlist check on raw URL. Better: tokenize raw text. Common approach: extract code spans and links from raw text first, replace with placeholders, escape remaining text, apply bold/italic, then substitute placeholders with safe content (escaped inner text or sanitized anchor).

Let me implement:

```js
function renderInline(raw) {
  const stash = [];
  function keep(html) { stash.push(html); return `\u0000${stash.length - 1}\u0000`; }

  // 1) inline code
  let out = raw.replace(/`([^`]+)`/g, (_, code) => keep(`<code>${escapeHtml(code)}</code>`));

  // 2) links [text](href)
  out = out.replace(/\[([^\]]+)\]\(([^)\s]*)\)/g, (_, text, href) => {
    const clean = href.trim();
    if (isSafeUrl(clean)) {
      return keep(`<a href="${escapeHtml(clean)}" rel="noopener noreferrer" target="_blank">${renderInlineNoLinks(text)}</a>`);
    }
    return keep(escapeHtml(`[${text}](${clean})`)); // plain text
  });

  // 3) escape everything else
  out = escapeHtml(out);

  // 4) bold & italic
  out = out.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  out = out.replace(/\*([^*]+)\*/g, '<em>$1</em>');

  // restore placeholders
  out = out.replace(/\u0000(\d+)\u0000/g, (_, i) => stash[i]);
  // also placeholders inside stash entries? Links nested in bold etc. Placeholder digits are fine after escaping since \u0000 isn't escaped... wait escapeHtml doesn't touch \u0000. Good.
  return out;
}
```

Wait: placeholder restoration after escaping — placeholders contain \u0000 which survives escaping. But if a link is inside bold like **[text](url)**, the link was stashed before escaping, so the placeholder gets escaped-wrapped by strong. Fine.

But careful: bold regex applied to escaped text — `**` unaffected by escaping. Fine.

isSafeUrl:
```js
function isSafeUrl(url) {
  const u = url.trim();
  if (/^(https?:|mailto:)/i.test(u)) return true;
  if (/^[/#.?]/.test(u) && !/^[a-z][a-z0-9+.-]*:/i.test(u)) return true; // relative
  if (!/^[a-z][a-z0-9+.-]*:/i.test(u)) return true; // no scheme → relative
  return false;
}
```
Simpler: parse scheme; allow http, https, mailto; allow scheme-less as relative; reject everything else (javascript:, data:, vbscript:, etc.). Also handle whitespace/control chars inside scheme like "java\tscript:" — browsers strip tabs/newlines. To be safe, remove all whitespace/control chars before testing: `const cleaned = url.replace(/[�-]/g,'')` then test. If original differs but scheme matches after cleaning... Actually safest: normalize by removing control chars/whitespace, lowercase, check scheme against allowlist.

```js
export function isSafeUrl(url) {
  const cleaned = String(url).replace(/[\s\u0000-\u001f]+/g, '');
  const m = /^([a-zA-Z][a-zA-Z0-9+.\-]*):/.exec(cleaned);
  if (!m) return true; // relative
  const scheme = m[1].toLowerCase();
  return ['http', 'https', 'mailto'].includes(scheme);
}
```

Block rendering:

```js
export function renderMarkdown(src) {
  const lines = String(src).split(/\r?\n/);
  const html = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (/^```/.test(line.trim())) {
      const buf = [];
      i++;
      while (i < lines.length && !/^```\s*$/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
      i++; // skip closing fence (or EOF)
      html.push(`<pre><code>${escapeHtml(buf.join('\n'))}</code></pre>`);
      continue;
    }
    if (/^[-*]\s+/.test(line.trim())) {
      const items = [];
      while (i < lines.length && /^[-*]\s+/.test(lines[i].trim())) {
        items.push(`<li>${renderInline(lines[i].trim().replace(/^[-*]\s+/, ''))}</li>`);
        i++;
      }
      html.push(`<ul>${items.join('')}</ul>`);
      continue;
    }
    if (line.trim() === '') { i++; continue; }
    // paragraph: gather until blank line / fence / list
    const para = [line];
    i++;
    while (i < lines.length && lines[i].trim() !== '' && !/^```/.test(lines[i].trim()) && !/^[-*]\s+/.test(lines[i].trim())) {
      para.push(lines[i]); i++;
    }
    html.push(`<p>${renderInline(para.join('\n'))}</p>`);
  }
  return html.join('\n');
}
```

Tests (tests/render.test.js) using node-html-parser:

- paragraphs: `<p>`
- bold, italics, inline code structure
- fenced code block: pre > code with escaped script tags
- links: safe https link has attrs rel noopener noreferrer target _blank
- javascript: link → plain text, no <a>
- data: link → plain text
- `<img src=x onerror=alert(1)>` renders escaped text; assert no img element, no on* attributes anywhere in tree
- payload suite: array of vectors, walk tree asserting no script/img/iframe/svg elements, no attribute starting with "on", no javascript:/data: hrefs.
- lists: ul/li

Walk helper:
```js
function walk(node, fn) { fn(node); node.childNodes.forEach(c => walk(c, fn)); }
```

