result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/mini-md/src/render.js", "content": "/**
 * mini-md — a tiny hand-rolled Markdown subset renderer.
 *
 * Supported: paragraphs, **bold**, *italics*, `inline code`,
 * ``` fenced code blocks ```, [links](url), and unordered lists.
 *
 * Security model:
 *  - All source text is HTML-escaped BEFORE any markup is inserted.
 *    Inline code spans and link nodes are extracted from the raw text
 *    and stashed as placeholders so their content can never be
 *    re-interpreted as markup.
 *  - Link hrefs must pass a scheme allowlist (http, https, mailto,
 *    or scheme-less relative URLs). Anything else (javascript:, data:,
 *    vbscript:, ...) renders as literal plain text.
 *  - Every emitted <a> gets rel="noopener noreferrer" target="_blank".
 */

const ALLOWED_SCHEMES = new Set(['http', 'https', 'mailto']);

/** Escape all HTML-significant characters. */
export function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Allowlist check for link destinations.
 * Browsers strip tabs/newlines/control chars from URLs before parsing the
 * scheme ("java\tscript:" is executable), so we normalize the same way
 * before testing. Scheme-less URLs are treated as relative and allowed.
 */
export function isSafeUrl(url) {
  const cleaned = String(url).replace(/[\u0000-\u0020]+/g, '');
  const match = /^([a-zA-Z][a-zA-Z0-9+.\-]*):/.exec(cleaned);
  if (!match) return true; // no scheme => relative URL
  return ALLOWED_SCHEMES.has(match[1].toLowerCase());
}

const PLACEHOLDER_RE = /\u0000(\d+)\u0000/g;

function makeStash() {
  const stash = [];
  return {
    keep(html) {
      stash.push(html);
      return `\u0000${stash.length - 1}\u0000`;
    },
    restore(text) {
      return text.replace(PLACEHOLDER_RE, (_, i) => stash[Number(i)]);
    },
  };
}

/** Render inline constructs with NO link recursion (used for link text). */
function renderInlineText(raw) {
  const { keep, restore } = makeStash();
  let out = raw.replace(/`([^`]+)`/g, (_, code) =>
    keep(`<code>${escapeHtml(code)}</code>`)
  );
  out = escapeHtml(out);
  out = out.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  out = out.replace(/\*([^*\n]+)\*/g, '<em>$1</em>');
  return restore(out);
}

/** Render inline constructs: code spans, links, bold, italics. */
export function renderInline(raw) {
  const { keep, restore } = makeStash();

  // 1. Inline code first: contents are literal, never re-parsed.
  let out = raw.replace(/`([^`]+)`/g, (_, code) =>
    keep(`<code>${escapeHtml(code)}</code>`)
  );

  // 2. Links: [text](href). Unsafe hrefs collapse to plain text.
  out = out.replace(/\[([^\]]*)\]\(([^)\s]*)\)/g, (_, text, href) => {
    if (isSafeUrl(href)) {
      const inner = renderInlineText(text);
      return keep(
        `<a href="${escapeHtml(href)}" rel="noopener noreferrer" target="_blank">${inner}</a>`
      );
    }
    // Dangerous destination: render the whole construct as escaped text.
    return keep(escapeHtml(`[${text}](${href})`));
  });

  // 3. Escape everything that is left, then apply emphasis markup.
  out = escapeHtml(out);
  out = out.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  out = out.replace(/\*([^*\n]+)\*/g, '<em>$1</em>');

  // 4. Restore safe, pre-built fragments.
  return restore(out);
}

const FENCE_OPEN = /^\s*```/;
const FENCE_CLOSE = /^\s*```\s*$/;
const LIST_ITEM = /^\s*[-*]\s+(.*)$/;

/** Render a full Markdown document to an HTML string. */
export function renderMarkdown(source) {
  const lines = String(source).split(/\r?\n/);
  const blocks = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Fenced code block: raw lines, escaped, inside <pre><code>.
    if (FENCE_OPEN.test(line)) {
      const buf = [];
      i += 1;
      while (i < lines.length && !FENCE_CLOSE.test(lines[i])) {
        buf.push(lines[i]);
        i += 1;
      }
      i += 1; // consume closing fence (or hit EOF)
      blocks.push(`<pre><code>${escapeHtml(buf.join('\n'))}</code></pre>`);
      continue;
    }

    // Unordered list: consecutive "- item" / "* item" lines.
    const listItem = LIST_ITEM.exec(line);
    if (listItem) {
      const items = [];
      while (i < lines.length) {
        const m = LIST_ITEM.exec(lines[i]);
        if (!m) break;
        items.push(`<li>${renderInline(m[1])}</li>`);
        i += 1;
      }
      blocks.push(`<ul>${items.join('')}</ul>`);
      continue;
    }

    // Blank line: paragraph separator.
    if (line.trim() === '') {
      i += 1;
      continue;
    }

    // Paragraph: gather until blank line, fence, or list start.
    const para = [line];
    i += 1;
    while (
      i < lines.length &&
      lines[i].trim() !== '' &&
      !FENCE_OPEN.test(lines[i]) &&
      !LIST_ITEM.test(lines[i])
    ) {
      para.push(lines[i]);
      i += 1;
    }
    blocks.push(`<p>${renderInline(para.join('\n'))}</p>`);
  }

  return blocks.join('\n');
}
