result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/mini-md/tests/render.test.js", "content": "import { describe, it, expect } from 'vitest';
import { parse } from 'node-html-parser';
import { renderMarkdown, escapeHtml, isSafeUrl } from '../src/render.js';

/** Depth-first walk over every node in the parsed tree. */
function walk(node, fn) {
  fn(node);
  for (const child of node.childNodes) walk(child, fn);
}

function elementsOf(html) {
  const root = parse(html);
  const els = [];
  walk(root, (n) => {
    if (n.nodeType === 1) els.push(n);
  });
  return { root, els };
}

/**
 * Security invariants applied to any rendered output:
 *  - no script/img/iframe/svg/object/embed/link element anywhere
 *  - no attribute whose name starts with "on"
 *  - no javascript:/data:/vbscript: URL in any href/src/action
 */
function assertSanitized(html) {
  const { root, els } = elementsOf(html);
  for (const el of els) {
    expect(
      ['script', 'img', 'iframe', 'svg', 'object', 'embed', 'link', 'math'],
      `forbidden element <${el.rawTagName}> in: ${html}`
    ).not.toContain(el.rawTagName?.toLowerCase());
    for (const attr of Object.keys(el.attributes)) {
      expect(
        attr.toLowerCase().startsWith('on'),
        `event handler "${attr}" in: ${html}`
      ).toBe(false);
      const value = (el.getAttribute(attr) ?? '').replace(/[\s\u0000-\u0020]/g, '').toLowerCase();
      expect(
        /^(javascript|data|vbscript):/.test(value),
        `dangerous URL in ${attr}="${el.getAttribute(attr)}" in: ${html}`
      ).toBe(false);
    }
  }
  return root;
}

describe('escapeHtml', () => {
  it('escapes all HTML-significant characters', () => {
    expect(escapeHtml(`<a href="x">&'`)).toBe(
      '&lt;a href=&quot;x&quot;&gt;&amp;&#39;'
    );
  });
});

describe('isSafeUrl allowlist', () => {
  it.each([
    ['https://example.com', true],
    ['http://example.com', true],
    ['mailto:a@b.com', true],
    ['/relative/path', true],
    ['page.html', true],
    ['#anchor', true],
    ['javascript:alert(1)', false],
    ['JaVaScRiPt:alert(1)', false],
    ['java\tscript:alert(1)', false],
    ['java\nscript:alert(1)', false],
    [' javascript:alert(1)', false],
    ['data:text/html,<script>alert(1)</script>', false],
    ['vbscript:msgbox(1)', false],
  ])('%j -> %j', (url, safe) => {
    expect(isSafeUrl(url)).toBe(safe);
  });
});

describe('paragraphs', () => {
  it('wraps plain text in <p>', () => {
    expect(renderMarkdown('hello world')).toBe('<p>hello world</p>');
  });

  it('separates consecutive paragraphs with a blank line', () => {
    const html = renderMarkdown('one\n\ntwo');
    expect(html).toContain('<p>one</p>');
    expect(html).toContain('<p>two</p>');
  });
});

describe('bold and italics', () => {
  it('renders **bold** as <strong>', () => {
    const html = renderMarkdown('this is **bold** text');
    expect(html).toBe('<p>this is <strong>bold</strong> text</p>');
  });

  it('renders *italics* as <em>', () => {
    const html = renderMarkdown('this is *italic* text');
    expect(html).toBe('<p>this is <em>italic</em> text</p>');
  });

  it('does not mangle markup when emphasis wraps unsafe content', () => {
    const html = renderMarkdown('**<script>alert(1)</script>**');
    expect(html).not.toContain('<script>');
    assertSanitized(html);
  });
});

describe('inline code', () => {
  it('wraps backtick content in <code> literally', () => {
    const html = renderMarkdown('run `npm test` now');
    expect(html).toBe('<p>run <code>npm test</code> now</p>');
  });

  it('never interprets HTML inside code spans', () => {
    const html = renderMarkdown('`<img src=x onerror=alert(1)>`');
    expect(html).toContain('&lt;img src=x onerror=alert(1)&gt;');
    assertSanitized(html);
  });
});

describe('fenced code blocks', () => {
  it('renders fenced content escaped inside pre > code', () => {
    const md = '```\n<script>alert(1)</script>\n<img src=x onerror=alert(1)>\n```';
    const html = renderMarkdown(md);
    const root = assertSanitized(html); // throws if any script/img survived

    const pre = root.querySelector('pre');
    expect(pre).toBeTruthy();
    const code = pre.querySelector('code');
    expect(code).toBeTruthy();
    // The payload survives only as inert, escaped TEXT content.
    expect(code.text).toContain('<script>alert(1)</script>');
    expect(code.innerHTML).toContain('&lt;script&gt;');
    expect(code.innerHTML).toContain('&lt;img src=x onerror=alert(1)&gt;');
  });
});

describe('links', () => {
  it('renders a safe link with rel/target hardening', () => {
    const html = renderMarkdown('[site](https://example.com)');
    const a = parse(html).querySelector('a');
    expect(a).toBeTruthy();
    expect(a.getAttribute('href')).toBe('https://example.com');
    expect(a.getAttribute('rel')).toBe('noopener noreferrer');
    expect(a.getAttribute('target')).toBe('_blank');
    expect(a.text).toBe('site');
  });

  it('allows mailto and relative destinations', () => {
    for (const href of ['mailto:a@b.com', '/docs/page.html']) {
      const a = parse(renderMarkdown(`[x](${href})`)).querySelector('a');
      expect(a?.getAttribute('href')).toBe(href);
      expect(a?.getAttribute('rel')).toBe('noopener noreferrer');
    }
  });

  it('collapses javascript: links to plain text', () => {
    const html = renderMarkdown('[click](javascript:alert(1))');
    expect(parse(html).querySelector('a')).toBeNull();
    expect(html).toContain('[click](javascript:alert(1))');
    assertSanitized(html);
  });

  it('collapses data: links to plain text', () => {
    const html = renderMarkdown('[click](data:text/html;base64,PHNjcmlwdD4=)');
    expect(parse(html).querySelector('a')).toBeNull();
    assertSanitized(html);
  });
});

describe('unordered lists', () => {
  it('renders "- " lines as ul > li', () => {
    const html = renderMarkdown('- one\n- two\n- three');
    const root = parse(html);
    expect(root.querySelectorAll('ul')).toHaveLength(1);
    const items = root.querySelectorAll('li');
    expect(items.map((li) => li.text.trim())).toEqual(['one', 'two', 'three']);
  });

  it('sanitizes markup inside list items', () => {
    const html = renderMarkdown('- **bold** item\n- <img src=x onerror=alert(1)>');
    const root = assertSanitized(html);
    expect(root.querySelector('ul')).toBeTruthy();
    expect(root.querySelectorAll('li')).toHaveLength(2);
  });
});

describe('XSS payload suite', () => {
  const payloads = [
    '[click](javascript:alert(1))',
    '[click](JaVaScRiPt:alert(1))',
    '[click](  javascript:alert(1))',
    '[click](jav\tascript:alert(1))',
    '[click](java\nscript:alert(1))',
    '<img src=x onerror=alert(1)>',
    '<IMG SRC=x ONERROR=alert(1)>',
    '<script>alert(1)</script>',
    '<SCRIPT SRC=http://evil.com/x.js></SCRIPT>',
    '<body onload=alert(1)>',
    '<svg onload=alert(1)>',
    '<iframe src="javascript:alert(1)"></iframe>',
    '<a href="javascript:alert(1)">x</a>',
    '<a href="data:text/html,<script>alert(1)</script>">x</a>',
    '<div onmouseover="alert(1)">hover</div>',
    '"><script>alert(1)</script>',
    "'-alert(1)-'",
    '`<img src=x onerror=alert(1)>`',
    '**<img src=x onerror=alert(1)>**',
    '- [click](javascript:alert(1))',
    '```\n<script>alert(1)</script>\n```',
    '![](javascript:alert(1))[x](data:text/html,y)',
  ];

  it.each(payloads)('is neutralized: %j', (payload) => {
    const html = renderMarkdown(payload);
    assertSanitized(html);
  });

  it('mixed benign + malicious document stays sanitized end to end', () => {
    const doc = [
      '# not-a-heading, just text',
      '',
      'Hello **world**, see [docs](https://example.com) or `[code]`.',
      '',
      '- item *one*',
      '- evil <img src=x onerror=alert(1)>',
      '- [trap](javascript:alert(1))',
      '',
      '```',
      '<script>alert("fenced")</script>',
      '```',
    ].join('\n');

    const html = renderMarkdown(doc);
    const root = assertSanitized(html);

    // Benign structure survived intact.
    expect(root.querySelector('p')).toBeTruthy();
    expect(root.querySelector('strong')?.text).toBe('world');
    expect(root.querySelector('a')?.getAttribute('href')).toBe('https://example.com');
    expect(root.querySelector('pre code')?.text).toContain('<script>alert("fenced")</script>');

    // Malicious bits are present only as escaped text.
    expect(root.querySelector('img')).toBeNull();
    expect(root.querySelector('script')).toBeNull();
  });
});
"})
